var PLACES=[
/* ── MAKKAH · The Haram ── */
{id:'haram',ll:[21.4225,39.8262],city:'makkah',g:'haram',i:'🕋',n:'Masjid al-Haram & the Kaaba',q:'Masjid al-Haram Makkah',d:'The House of Allah, qibla of the world, site of your tawaf. "The first House established for mankind" (Quran 3:96); every prayer here is worth 100,000 (Ibn Majah 1406).',tip:'Landmarks inside: Hajar al-Aswad, Maqam Ibrahim, Hijr Isma’il, the Multazam & the Yamani corner.'},
{id:'hijr',ll:[21.4225,39.8262],city:'makkah',g:'haram',i:'🌙',n:'Hijr Isma’il & Maqam Ibrahim',q:'Masjid al-Haram Makkah',d:'The semicircle beside the Kaaba was part of Ibrahim’s original building — praying inside it counts as praying inside the Kaaba (Tirmidhi 876). Maqam Ibrahim is the stone he stood on while raising the walls (Quran 2:125).',tip:'Try the Hijr late at night after tawaf; pray your 2 rakahs anywhere behind the Maqam if the area is packed.'},
{id:'zamzam',ll:[21.4225,39.8262],city:'makkah',g:'haram',i:'💧',n:'The Well of Zamzam',q:'Zamzam Well Makkah',d:'Sprang at baby Isma’il’s feet as Hajar searched between the hills (Bukhari 3364). "Zamzam water is for whatever it is drunk for" (Ibn Majah 3062).',tip:'The well itself is now beneath the mataf; chilled and room-temperature dispensers are on every floor. Face the qibla and make dua as you drink.'},
{id:'safa',ll:[21.4234,39.8278],city:'makkah',g:'haram',i:'⛰️',n:'Safa & Marwah (the Mas’a)',q:'Safa and Marwah Makkah',d:'"Indeed Safa and Marwah are among the symbols of Allah" (Quran 2:158). The two hills of Hajar’s seven runs, now an air-conditioned 450 m gallery inside the mosque.',tip:'Wheelchair lanes run down the middle; the green lights mark where men jog. Begin at Safa, finish at Marwah.'},
/* ── MAKKAH · Ziyarah ── */
{id:'hira',ll:[21.4575,39.8595],city:'makkah',g:'ziyarah',i:'⛰️',n:'Jabal an-Nour & the Cave of Hira',q:'Jabal al-Nour Makkah',d:'Where the first revelation "Iqra" descended upon the Prophet ﷺ (Bukhari 3).',tip:'A steep 45–90 min climb — go after Fajr, take water. Viewing from below also suffices; see the Revelation Exhibition at its foot.'},
{id:'thawr',ll:[21.3776,39.8438],city:'makkah',g:'ziyarah',i:'🏔️',n:'Jabal Thawr',q:'Jabal Thawr Makkah',d:'The cave where the Prophet ﷺ and Abu Bakr hid for three nights during the Hijrah — "Do not grieve; indeed Allah is with us" (Quran 9:40).',tip:'A tougher climb than Hira; most pilgrims view it from the road on a ziyarah tour.'},
{id:'birth',ll:[21.423,39.83],city:'makkah',g:'ziyarah',i:'🏠',n:'Birthplace of the Prophet ﷺ (Makkah Library)',q:'Makkah Al Mukarramah Library',d:'By long-standing tradition the site of the house of Aminah where the Prophet ﷺ was born in the Year of the Elephant, in the Shi’b Ali quarter. Today it houses a library.',tip:'A few minutes’ walk from the Safa side of the Haram. Viewed from outside — it is not a place of worship; reflect, don’t ritualise.'},
{id:'abuqubays',ll:[21.4225,39.83],city:'makkah',g:'ziyarah',i:'🏔️',n:'Jabal Abu Qubays',q:'Jabal Abu Qubais Makkah',d:'The mountain rising directly east of the Haram, held by tradition to be the first mountain placed on earth and the place the Black Stone was safeguarded during the flood.',tip:'Now crowned by a royal palace; visible from the Safa end of the mataf — no visit needed.'},
{id:'rayah',city:'makkah',g:'ziyarah',i:'🚩',n:'Masjid ar-Rayah',q:'Masjid Al Rayah Makkah',d:'"The Mosque of the Banner" — by tradition the spot where the Prophet ﷺ planted his standard as he entered Makkah at the Conquest of 8 AH, forgiving the city that had expelled him.',tip:'In the Jarwal district, ~15 min walk north-west of the Haram.'},
{id:'taneem',ll:[21.4693,39.8016],city:'makkah',g:'ziyarah',i:'🕌',n:'Masjid Aisha (Tan’eem)',q:'Masjid Aisha Taneem Makkah',d:'The nearest boundary of the Haram — where the Prophet ﷺ sent Aishah (RA) to take ihram for her Umrah (Bukhari 1784). Take ihram here for an additional Umrah.',tip:'10–15 min taxi; free buses often run. Showers and ihram shops on site.'},
{id:'jiranah',ll:[21.567,39.956],city:'makkah',g:'ziyarah',i:'🕌',n:'Masjid al-Ji’ranah',q:'Masjid Al Jiranah Makkah',d:'Where the Prophet ﷺ assumed ihram for his Umrah after the Battle of Hunayn (Bukhari 1778) — one of his four Umrahs. A miqat for those already in Makkah.',tip:'~25 km north-east; far calmer than Tan’eem for a second Umrah.'},
{id:'hudaybiyyah',ll:[21.438,39.696],city:'makkah',g:'ziyarah',i:'🌳',n:'Masjid al-Hudaybiyyah',q:'Masjid Al Hudaibiyah Makkah',d:'Site of the Treaty of Hudaybiyyah (6 AH) and the Pledge under the Tree — "Allah was pleased with the believers when they pledged allegiance to you under the tree" (Quran 48:18). Also a miqat on the western Haram boundary.',tip:'~25 km west on the Jeddah road; the old mosque ruins stand beside the modern one.'},
{id:'mualla',ll:[21.43,39.8283],city:'makkah',g:'ziyarah',i:'🌿',n:'Jannat al-Mu’alla',q:'Jannat al-Mualla Makkah',d:'Makkah’s ancient cemetery — resting place of Khadijah (RA), the Prophet’s ﷺ beloved first wife, and of his grandfather Abdul-Muttalib and uncle Abu Talib.',tip:'Give salam to the deceased; visiting hours are limited and entry is for men.'},
{id:'jinn',ll:[21.431,39.8288],city:'makkah',g:'ziyarah',i:'🕌',n:'Masjid al-Jinn',q:'Masjid al-Jinn Makkah',d:'Where a group of jinn listened to the Prophet ﷺ reciting Quran and embraced Islam — the event behind Surah al-Jinn (72).',tip:'A short walk north of the Haram, near Jannat al-Mu’alla.'},
/* ── MAKKAH · Hajj sites ── */
{id:'arafat',ll:[21.3549,39.9841],city:'makkah',g:'hajj',i:'🌄',n:'Mount Arafat & Jabal ar-Rahmah',q:'Jabal ar-Rahmah Arafat',d:'The plain of the Farewell Sermon where Hajj reaches its peak — "Hajj is Arafah." Standing here on 9 Dhul-Hijjah is the heart of Hajj.',tip:'Combine Arafat, Muzdalifah & Mina in one half-day ziyarah taxi tour (agree the price first).'},
{id:'namirah',ll:[21.354,39.9707],city:'makkah',g:'hajj',i:'🕌',n:'Masjid Namirah (Arafat)',q:'Masjid Namirah Arafat',d:'The Prophet ﷺ had his tent pitched at Namirah on the day of Arafah, then addressed the people and prayed Dhuhr and Asr combined (Muslim 1218). One of the largest mosques in the world.',tip:'Opens only on the day of Arafah; outside Hajj you view it from the road.'},
{id:'muzdalifah',ll:[21.3833,39.9366],city:'makkah',g:'hajj',i:'🌌',n:'Muzdalifah',q:'Muzdalifah',d:'Where Hajj pilgrims sleep under the open sky between Arafat and Mina — named in the Quran as al-Mash’ar al-Haram (2:198).',tip:'Drive-through on a ziyarah tour; picture two million people sleeping here in one night.'},
{id:'mashar',city:'makkah',g:'hajj',i:'🕌',n:'Masjid al-Mash’ar al-Haram',q:'Masjid Al Mashar Al Haram Muzdalifah',d:'Marks the spot where the Prophet ﷺ stood at Muzdalifah making dua until the sky brightened — "remember Allah at al-Mash’ar al-Haram" (Quran 2:198).',tip:'Between Arafat and Mina on the pilgrim road.'},
{id:'mina',ll:[21.4133,39.8933],city:'makkah',g:'hajj',i:'⛺',n:'Mina',q:'Mina Makkah',d:'The tent city of Hajj — 100,000 fireproof tents — and the site of the Jamarat and the sacrifice.',tip:'Quiet outside Hajj season — a moving drive-through with Quran 22:27 in mind.'},
{id:'khayf',ll:[21.419,39.888],city:'makkah',g:'hajj',i:'🕌',n:'Masjid al-Khayf (Mina)',q:'Masjid Al Khaif Mina',d:'The great mosque of Mina where the Prophet ﷺ prayed during his Hajj; narrations reported by at-Tabarani say many prophets before him prayed in this valley.',tip:'Holds 45,000; outside Hajj it is open and near-empty — pray two rakahs.'},
{id:'bayah',city:'makkah',g:'hajj',i:'🤝',n:'Masjid al-Bay’ah (Aqabah)',q:'Masjid Al Bayah Mina',d:'Where the people of Madinah secretly pledged allegiance to the Prophet ﷺ in the two Pledges of Aqabah (621–622 CE) — the moment that opened the door to the Hijrah.',tip:'A small, easily-missed mosque near the Jamarat bridge; built in 144 AH.'},
{id:'jamarat',ll:[21.4224,39.8735],city:'makkah',g:'hajj',i:'🪨',n:'The Jamarat',q:'Jamarat Bridge Mina',d:'The three pillars marking where Ibrahim (AS) stoned Shaytan when tempted to disobey — re-enacted by every Hajj pilgrim on the days of Tashriq.',tip:'The multi-level bridge is an engineering marvel; visit outside Hajj to understand the layout before you ever come for Hajj.'},
/* ── MAKKAH · Museums & culture ── */
{id:'hirac',ll:[21.456,39.857],city:'makkah',g:'museum',i:'🏛️',n:'Hira Cultural District & Revelation Exhibition',q:'Hira Cultural District Makkah',d:'A modern museum at the foot of Jabal an-Nour telling the story of wahy (revelation) with immersive exhibits — the context for everything you recite.',tip:'The perfect alternative to the climb for the elderly and children. Book online; evening slots are cooler.'},
{id:'exhibition',city:'makkah',g:'museum',i:'🏛️',n:'Exhibition of the Two Holy Mosques',q:'Exhibition of the Two Holy Mosques Architecture Makkah',d:'Historic Kaaba doors, kiswah textiles, the old Zamzam well-head, Maqam Ibrahim casings and rare artefacts of the Haramain across the centuries.',tip:'Free entry; on the old Jeddah road. Check hours before going.'},
{id:'kiswah',city:'makkah',g:'museum',i:'🧵',n:'The Kiswah Factory (King Abdulaziz Complex)',q:'Kiswa Factory Makkah',d:'Where the black silk covering of the Kaaba is woven each year and embroidered with 120 kg of gold and silver thread — a craft of honouring the House that is centuries old.',tip:'Visits are by arrangement/tour; the exhibition explains every panel of calligraphy you see on the Kaaba.'},
{id:'makkahmuseum',city:'makkah',g:'museum',i:'🏛️',n:'Makkah Museum (Al-Zahir Palace)',q:'Makkah Museum Al Zahir Palace',d:'The history of the Hijaz from pre-Islamic times through the prophetic era to the modern Kingdom, in a 1940s palace.',tip:'Mornings, weekdays; combine with the Exhibition of the Two Holy Mosques nearby.'},
{id:'clock',ll:[21.4187,39.8256],city:'makkah',g:'museum',i:'🕰️',n:'Makkah Clock Tower Museum',q:'Clock Tower Museum Makkah',d:'Astronomy and Islamic timekeeping museum atop the Abraj al-Bait — four floors, then a breathtaking balcony view over the Haram.',tip:'Book in advance; sunset slots have the best views.'},
/* ── MAKKAH · Day trips ── */
{id:'taif',ll:[21.2705,40.4158],city:'makkah',g:'trip',i:'🌹',n:'Ta’if & Masjid Abdullah ibn Abbas',q:'Masjid Abdullah Ibn Abbas Taif',d:'The mountain city that stoned the Prophet ﷺ in the 10th year of his mission — when the Angel of the Mountains offered to crush it, he refused, hoping for believing descendants (Bukhari 3231). Today: cool air, rose farms, and the mosque of Ibn Abbas (RA).',tip:'~1.5 h by road up the escarpment. Wadi Muharram on the way is a miqat if you return in ihram.'},
{id:'jeddah',ll:[21.4858,39.1875],city:'makkah',g:'trip',i:'🏘️',n:'Historic Jeddah (Al-Balad)',q:'Al Balad Jeddah',d:'The UNESCO-listed old town that was the sea gate of pilgrims to Makkah for thirteen centuries — coral-stone houses, wooden rawashin balconies, ancient mosques.',tip:'An evening stroll on the way to the airport. A cultural, not religious, visit.'},
/* ── MADINAH · The Prophet’s Mosque & around ── */
{id:'nabawi',ll:[24.4672,39.6111],city:'madinah',g:'mharam',i:'🕌',n:'Masjid an-Nabawi',q:'Al Masjid an Nabawi Madinah',d:'The Prophet’s ﷺ mosque, built with his own hands — one prayer here is better than a thousand elsewhere (Bukhari 1190).',tip:'Give salam to the Prophet ﷺ and his two companions with calm and lowered voice.',stop:'G1'},
{id:'rawdah',ll:[24.4672,39.6111],city:'madinah',g:'mharam',i:'🌹',n:'The Rawdah',q:'Al Masjid an Nabawi Madinah',d:'"Between my house and my minbar is a garden from the gardens of Paradise" (Bukhari 1195).',tip:'Requires a free timed permit on the Nusuk app — book the moment your dates are fixed.'},
{id:'babsalam',ll:[24.4677,39.6104],city:'madinah',g:'mharam',i:'🚪',n:'Bab as-Salam (Al Salam Gate)',q:'Bab As Salam Al Masjid an Nabawi',d:'The historic western gate of the mosque — for centuries the traditional entrance by which visitors approach to greet the Prophet ﷺ, Abu Bakr and ’Umar.',tip:'Walk it slowly with salawat on your lips; no crowding, no raised voices.',stop:'G4'},
{id:'baqi',ll:[24.4668,39.6169],city:'madinah',g:'mharam',i:'🌿',n:'Jannat al-Baqi’',q:'Al Baqi Cemetery Madinah',d:'Resting place of ’Uthman (RA), the Prophet’s ﷺ wives and daughters, his son Ibrahim, and some ten thousand companions.',tip:'Open after Fajr and Asr; entry for men. Give the sunnah salam to the people of the graves.',stop:'G2'},
{id:'manakha',ll:[24.4672,39.608],city:'madinah',g:'mharam',i:'🏙️',n:'Al Manakha Square',q:'Al Manakha Square Madinah',d:'The old caravan-halt and market ground west of the mosque — the Prophet ﷺ moved Madinah’s market here, saying "this is your market". Masjid al-Ghamamah stands on its edge.',tip:'Dates, cafés and evening buzz; a good meeting point for families.',stop:'G3'},
{id:'quranmuseum',city:'madinah',g:'mharam',i:'📖',n:'Exhibition of the Holy Quran & the Prophet’s Biography',q:'International Fair and Museum of the Prophet Biography Madinah',d:'Two museums beside the Haram: rare mushafs and the science of the Quran, and a sensory walk through the seerah.',tip:'Wonderful with children; tours in many languages.'},
/* ── MADINAH · Historic mosques ── */
{id:'quba',ll:[24.4396,39.6172],city:'madinah',g:'mosques',i:'🕌',n:'Masjid Quba',q:'Quba Mosque Madinah',d:'The first mosque of Islam, "founded on taqwa" (Quran 9:108). Praying 2 rakahs here with wudu from home earns the reward of an Umrah (Ibn Majah 1412).',tip:'The Prophet ﷺ visited every Saturday, walking or riding (Bukhari 1194) — make wudu at your hotel and go at least once.',stop:'R6'},
{id:'qiblatain',ll:[24.4842,39.5934],city:'madinah',g:'mosques',i:'🕌',n:'Masjid al-Qiblatayn',q:'Masjid al-Qiblatayn Madinah',d:'Where the revelation to turn the qibla from Jerusalem to Makkah came mid-prayer (Quran 2:144) — the congregation turned as one.',tip:'A short ride north-west of the Haram; combine with the Seven Mosques.',stop:'R4'},
{id:'jumuah',ll:[24.4497,39.6153],city:'madinah',g:'mosques',i:'🕌',n:'Masjid al-Jumu’ah',q:'Masjid Al Jumuah Madinah',d:'In the valley of Ranuna, where the Prophet ﷺ prayed the first Friday prayer in Islam on the way from Quba into Madinah after the Hijrah.',tip:'Halfway along Quba Avenue — stop here if you walk to Quba.'},
{id:'ijabah',ll:[24.4737,39.618],city:'madinah',g:'mosques',i:'🤲',n:'Masjid al-Ijabah',q:'Masjid Al Ijabah Madinah',d:'The mosque of Banu Mu’awiyah where the Prophet ﷺ prayed and made a long dua: "I asked my Lord three things — He granted me two and withheld one" (Muslim 2890).',tip:'5 min from Baqi on Sitteen Street; pray two rakahs and make your own long dua.'},
{id:'ghamamah',ll:[24.4665,39.6096],city:'madinah',g:'mosques',i:'🕌',n:'Masjid al-Ghamamah',q:'Masjid al-Ghamamah Madinah',d:'Where the Prophet ﷺ prayed Eid and istisqa (the rain prayer) — a cloud (ghamamah) is said to have shaded him here.',tip:'A 5-minute walk south-west of Masjid an-Nabawi, beside Al Manakha.'},
{id:'miqat',ll:[24.4137,39.5433],city:'madinah',g:'mosques',i:'🤍',n:'Masjid al-Miqat (Dhul-Hulayfah / Abyar Ali)',q:'Masjid Al Miqat Abyar Ali Madinah',d:'The miqat the Prophet ﷺ appointed for the people of Madinah (Bukhari 1524) — where you will assume ihram before travelling to Makkah, as he did.',tip:'9 km south-west. Showers, wudu areas and ihram shops on site; the Haramain train and most buses stop here on request.'},
/* ── MADINAH · Battlefields, wells & history ── */
{id:'uhud',ll:[24.504,39.613],city:'madinah',g:'history',i:'⛰️',n:'Mount Uhud & the Martyrs’ Cemetery',q:'Mount Uhud Madinah',d:'Site of the Battle of Uhud (3 AH) — resting place of Hamza (RA) and seventy martyrs. "Uhud is a mountain that loves us and we love it" (Bukhari 4083).',tip:'Visit after Fajr before the heat; give salam at the martyrs’ fence and climb the Archers’ Hill to understand the battle.',stop:'R1'},
{id:'khandaq',ll:[24.474,39.599],city:'madinah',g:'history',i:'🕌',n:'The Trench Battlefield & the Seven Mosques',q:'Seven Mosques Madinah',d:'Where the Muslims dug the trench at the foot of Mount Sila’ in 5 AH and Allah sent the wind against the confederates (Quran 33:9). Small mosques mark the posts of the Prophet ﷺ, Salman, Abu Bakr, ’Umar, ’Ali and Fatimah.',tip:'Masjid al-Fath on the hill is where the Prophet ﷺ prayed for victory. Minutes from Qiblatayn.',stop:'R5'},
{id:'aqiq',city:'madinah',g:'history',i:'🏞️',n:'Wadi al-Aqiq',q:'Wadi Al Aqiq Madinah',d:'"A messenger came to me from my Lord and said: pray in this blessed valley" (Bukhari 1534). The valley of Madinah’s old estates and the path to the miqat.',tip:'You cross it on the way to Masjid al-Miqat — look out for it.'},
{id:'biruthman',city:'madinah',g:'history',i:'💧',n:'Bir Uthman (the Well of Rumah)',q:'Bir Uthman Madinah',d:'’Uthman (RA) bought this well and made it free for all Muslims after the Prophet ﷺ said: "Whoever buys the well of Rumah will have Paradise" (Bukhari 2778, Tirmidhi 3703). Its endowment still funds charity 1,400 years later.',tip:'A working date farm north of the city; a lesson in sadaqah jariyah.'},
{id:'salman',city:'madinah',g:'history',i:'🌴',n:'Garden of Salman al-Farisi',q:'Salman Al Farsi Garden Madinah',d:'The palm garden associated with Salman’s (RA) freedom — reports say the Prophet ﷺ planted the date palms with his own hands to pay the price of his manumission.',tip:'Near Quba; a quiet place to reflect on a seeker who crossed empires to find the truth.'},
{id:'hijazrail',ll:[24.4653,39.605],city:'madinah',g:'history',i:'🚂',n:'Al Hijaz Railway Station & Museum',q:'Hejaz Railway Museum Madinah',d:'The 1908 Ottoman terminus of the Damascus–Madinah line, built to carry pilgrims to the Haramain. The restored station is now a museum of Madinah’s history and the railway.',tip:'Check opening — parts have been closed for restoration. Hop-on hop-off stop.',stop:'R7'},
{id:'darmadinah',city:'madinah',g:'history',i:'🏛️',n:'Dar Al Madinah Museum',q:'Dar Al Madinah Museum',d:'The seerah and the history of Madinah with detailed models of the city across the ages.',tip:'Excellent with kids; guided tours available in English.'},
/* ── MADINAH · Hop-on hop-off & practical ── */
{id:'qubasq',ll:[24.445,39.616],city:'madinah',g:'tour',i:'🚶',n:'Quba Square & Quba Avenue',q:'Quba Avenue Madinah',d:'The 3 km palm-lined pedestrian avenue from the Haram to Masjid Quba — walk it as the Prophet ﷺ did on his Saturday visits (Bukhari 1194).',tip:'Walk it at sunset; the bus brings you back. Hop-on hop-off stop.',stop:'R8'},
{id:'noormall',city:'madinah',g:'tour',i:'🛍️',n:'Al-Noor Mall',q:'Al Noor Mall Madinah',d:'Madinah’s largest mall — a practical hop-off for food courts, kids’ areas, pharmacies and gifts.',tip:'Handy between Uhud and Qiblatayn on the Red route.',stop:'R2'},
{id:'sultanah',city:'madinah',g:'tour',i:'🍽️',n:'Sultanah — Abu Bakr as-Siddiq Road',q:'Sultanah Road Madinah',d:'The main restaurant and shopping strip — Madinah dates, perfume, and the city’s best-known eateries.',tip:'Try the local Ajwa dates and the famous Madinah bukhari rice.',stop:'R3'}];

var QUIZ_LEVELS=[
{icon:'🕋',name:'Level 1 · Foundations of Umrah',desc:'What Umrah is and how it flows',study:{sub:'learn',id:'knowCard'},qs:[
{q:'Umrah is often called…',o:['The greater pilgrimage','The minor pilgrimage','The night journey','The farewell pilgrimage'],a:1,e:'Umrah is the "minor pilgrimage" — Hajj is the major one with fixed dates and extra rites.'},
{q:'True or false: Umrah can be performed at any time of the year.',tf:1,a:0,e:'True — unlike Hajj, Umrah has no fixed date. (Ramadan carries a special reward.)'},
{q:'The correct order of the Umrah rites is…',o:['Tawaf → Ihram → Sa’i → Halq','Ihram → Sa’i → Tawaf → Halq','Ihram → Tawaf → Sa’i → Halq/Taqsir','Sa’i → Tawaf → Ihram → Halq'],a:2,e:'Ihram at the miqat, then tawaf, then sa’i, then cutting the hair — in that order.'},
{q:'True or false: Umrah and Hajj are identical acts of worship.',tf:1,a:1,e:'False — Hajj adds Arafat, Muzdalifah, Mina and the fixed days of Dhul-Hijjah; Umrah is ihram, tawaf, sa’i and halq.'},
{q:'How many rounds (circuits) make one complete tawaf?',o:['3','5','7','10'],a:2,e:'Seven rounds, counter-clockwise, starting and ending at the Black Stone line.'},
{q:'Sa’i begins at… and ends at…',o:['Marwah → Safa','Safa → Marwah','Either direction','The mataf'],a:1,e:'"Begin with what Allah began with" — Quran 2:158 mentions Safa first; 7 laps ending at Marwah.'},
{q:'When does the pilgrim stop reciting the talbiyah in Umrah?',o:['At the hotel','On seeing the Kaaba','When beginning tawaf','After sa’i'],a:2,e:'The talbiyah continues from the miqat until you start your tawaf.'},
{q:'What does "Labbayk" mean?',o:['Forgive me','Here I am (at Your service)','Allah is greatest','Praise be to Allah'],a:1,e:'Labbayk Allahumma labbayk — "Here I am, O Allah, here I am," answering the call to pilgrimage.'},
{q:'True or false: children may perform Umrah, with guardians handling the rites for the very young.',tf:1,a:0,e:'True — the Prophet ﷺ confirmed a child’s pilgrimage counts (Muslim 1336); parents make intention for infants.'},
{q:'True or false: an accepted pilgrimage returns you "as the day your mother bore you".',tf:1,a:0,e:'True — whoever performs it without obscenity or sin returns cleansed of sins (Bukhari 1521, Muslim 1350).'}
]},
{icon:'🤍',name:'Level 2 · Ihram & the Miqats',desc:'The sacred state and its boundaries',study:{sub:'learn',id:'knowCard'},qs:[
{q:'The miqat for those travelling to Makkah from Madinah is…',o:['Yalamlam','Qarn al-Manazil','Al-Juhfah','Dhul-Hulayfah (Abyar Ali)'],a:3,e:'Dhul-Hulayfah, just outside Madinah — the farthest miqat from Makkah (~450 km).'},
{q:'Most flights arriving from the east (UAE, Pakistan, India…) cross which miqat?',o:['Qarn al-Manazil (As-Sayl)','Al-Juhfah','Dhat Irq','Yalamlam'],a:0,e:'Qarn al-Manazil serves Najd, Taif and most eastern arrivals — be in ihram before the pilot’s announcement.'},
{q:'Which of these is prohibited in ihram?',o:['Wearing a wristwatch','Showering with plain water','Applying perfume','Wearing sandals'],a:2,e:'Scented products are prohibited. Watches, glasses, belts and unscented showers are all fine.'},
{q:'True or false: men may wear a money belt or waist pouch in ihram.',tf:1,a:0,e:'True — a belt is not fitted "stitched clothing"; it is how you keep your passport and cash safe.'},
{q:'True or false: a woman must wear a niqab (face veil) in ihram.',tf:1,a:1,e:'False — the opposite: the niqab and gloves are specifically not worn in ihram (Bukhari 1838). Ordinary modest dress applies.'},
{q:'The two garments of a man’s ihram are called…',o:['Thobe & ghutrah','Izar & rida','Bisht & shemagh','Qamis & sirwal'],a:1,e:'The izar wraps the lower body, the rida drapes the upper body — both unstitched.'},
{q:'True or false: the intention for Umrah must be made before crossing the miqat.',tf:1,a:0,e:'True — crossing your miqat without ihram when intending Umrah requires returning to it or compensation (fidyah).'},
{q:'True or false: a pilgrim flying to Jeddah may delay ihram until after landing.',tf:1,a:1,e:'False — Jeddah lies inside the miqat boundaries for most routes, so ihram must be assumed before the plane crosses the miqat.'},
{q:'Which is NOT an ihram violation?',o:['Applying perfume','Trimming nails','Wearing prescription glasses','Proposing marriage'],a:2,e:'Glasses, watches, rings, umbrellas and sandals are all fine in ihram.'},
{q:'True or false: if you break an ihram rule by genuine mistake or forgetfulness, your Umrah is ruined.',tf:1,a:1,e:'False — "Our Lord, do not hold us to account for what we forget or err in" (Quran 2:286). Learn, correct, continue.'}
]},
{icon:'🔄',name:'Level 3 · Tawaf, Sa’i & Halq',desc:'The rites in fine detail',study:{sub:'learn',id:'knowCard'},rites:true,qs:[
{q:'Where does each round of tawaf begin?',o:['Maqam Ibrahim','The Black Stone (Hajar al-Aswad) corner','The Yamani corner','The Kaaba door'],a:1,e:'Face the Black Stone, say "Bismillahi wallahu akbar", then keep the Kaaba on your left.'},
{q:'What is raml?',o:['Brisk walking in the first 3 rounds of tawaf (men)','Jogging the whole sa’i','A type of dua','The stoning ritual'],a:0,e:'Men walk briskly with short steps in rounds 1–3 of the arrival tawaf only. Women walk normally.'},
{q:'True or false: wudu is required for tawaf.',tf:1,a:0,e:'True — tawaf is like prayer (Tirmidhi 960); keep your wudu, and renew it if broken.'},
{q:'True or false: each round of tawaf has its own fixed, prescribed dua.',tf:1,a:1,e:'False — no dua is prescribed per round. Only "Rabbana atina…" between the Yamani corner and Black Stone is sunnah.'},
{q:'You cannot reach the Black Stone. What do you do?',o:['Push through the crowd','Skip that round','Point towards it and say Allahu Akbar','Wait until it clears'],a:2,e:'Gesture from afar with "Allahu Akbar" and continue — harming others for a sunnah is never right.'},
{q:'What dua is sunnah between the Yamani corner and the Black Stone?',o:['The talbiyah','Rabbana atina fid-dunya hasanah…','Ayat al-Kursi','Surah al-Fatihah'],a:1,e:'"Our Lord, give us good in this world and good in the Hereafter, and protect us from the Fire." (Quran 2:201)'},
{q:'What is prayed immediately after tawaf?',o:['4 rakahs of Duha','2 rakahs behind Maqam Ibrahim','Salat al-Janazah','Nothing'],a:1,e:'Two rakahs behind Maqam Ibrahim (anywhere if crowded) — al-Kafirun then al-Ikhlas are sunnah.'},
{q:'True or false: Safa → Marwah counts as one full lap of sa’i.',tf:1,a:0,e:'True — one direction is one lap; seven laps finish on Marwah.'},
{q:'True or false: women jog between the green lights during sa’i.',tf:1,a:1,e:'False — the light jog there is for men; women walk throughout.'},
{q:'How does a woman exit ihram after sa’i?',o:['Shave her head','Trim a fingertip’s length of hair','Cut a single strand','Nothing required'],a:1,e:'Women trim about a fingertip’s length (~2 cm) from the ends — never shave.'},
{q:'True or false: for men, shaving the head (halq) carries more reward than trimming (taqsir).',tf:1,a:0,e:'True — the Prophet ﷺ made dua for those who shave three times, and once for those who trim (Bukhari 1727).'}
]},
{icon:'🕰️',name:'Level 4 · History of Makkah & the Kaaba',desc:'The story behind every rite',study:{sub:'learn',id:'histCard'},qs:[
{q:'Who raised the foundations of the Kaaba?',o:['Adam alone','Ibrahim & Isma’il','Quraysh','Musa & Harun'],a:1,e:'"And when Ibrahim was raising the foundations of the House with Isma’il…" (Quran 2:127).'},
{q:'The Kaaba is described in the Quran as…',o:['The first House established for mankind','The largest building of its time','A gift to Quraysh','The house of Adam'],a:0,e:'"The first House established for mankind was that at Bakkah — blessed and a guidance for the worlds." (Quran 3:96)'},
{q:'The well of Zamzam sprang for…',o:['Ibrahim on his journey','Hajar and baby Isma’il','The army of the Elephant','Quraysh pilgrims'],a:1,e:'Allah caused it to spring at baby Isma’il’s feet as Hajar ran between Safa and Marwah (Bukhari 3364).'},
{q:'Sa’i between Safa and Marwah commemorates…',o:['The Hijrah route','Hajar’s search for water','The conquest of Makkah','The Farewell Sermon'],a:1,e:'Your seven laps re-enact Hajar’s seven runs of pure trust in Allah — "Then He will not abandon us."'},
{q:'True or false: the Black Stone descended from Paradise whiter than milk.',tf:1,a:0,e:'True — "…and the sins of the children of Adam blackened it." (Tirmidhi 877)'},
{q:'How did the young Muhammad ﷺ resolve the Quraysh dispute over placing the Black Stone?',o:['He placed it himself secretly','He drew lots','He laid it on a cloth for all tribes to lift together','He told them to leave it out'],a:2,e:'Every tribe lifted a corner of the cloth, and al-Amin ﷺ set the Stone in place with his own hands.'},
{q:'The first revelation came to the Prophet ﷺ in…',o:['The cave of Thawr','Masjid al-Haram','The cave of Hira on Jabal an-Nour','Mina'],a:2,e:'"Iqra — Read!" (Quran 96:1) descended in Hira, the cave above Makkah (Bukhari 3).'},
{q:'True or false: Muslims always prayed towards the Kaaba from the beginning of Islam.',tf:1,a:1,e:'False — they first faced Jerusalem; the qibla changed mid-prayer (~2 AH) — Quran 2:144, commemorated at Masjid al-Qiblatayn.'},
{q:'Maqam Ibrahim is…',o:['Ibrahim’s grave','The stone he stood on while building the Kaaba','The door of the Kaaba','A minaret'],a:1,e:'The standing-stone of Ibrahim (AS) — "Take the Maqam of Ibrahim as a place of prayer." (Quran 2:125)'},
{q:'During the Hijrah, the Prophet ﷺ and Abu Bakr hid in…',o:['The cave of Hira','The cave of Thawr','Masjid Quba','Jabal Uhud'],a:1,e:'Three nights in Thawr — "Do not grieve; indeed Allah is with us." (Quran 9:40)'},
{q:'True or false: praying inside Hijr Isma’il counts as praying inside the Kaaba.',tf:1,a:0,e:'True — the semicircle was part of the original Kaaba (Tirmidhi 876). A rare chance most pilgrims miss!'}
]},
{icon:'🌟',name:'Level 5 · Virtues of Umrah & the Haram',desc:'The rewards that await you',study:{sub:'learn',id:'virtCard'},qs:[
{q:'"Umrah to Umrah is an expiation for…"',o:['All future sins','The sins committed between them','Major sins only','Debts'],a:1,e:'Bukhari 1773 — and the accepted Hajj has no reward but Paradise.'},
{q:'What does "an Umrah in Ramadan" equal, according to the Prophet ﷺ?',o:['10 Umrahs','A Hajj with him ﷺ','Laylatul Qadr','A year of fasting'],a:1,e:'"An Umrah in Ramadan is equal to a Hajj" (Bukhari 1863) — and in one narration: "a Hajj with me" (Muslim 1256).'},
{q:'One prayer in Masjid al-Haram equals how many elsewhere?',o:['1,000','10,000','50,000','100,000'],a:3,e:'100,000 prayers (Ibn Majah 1406) — one Fajr there outweighs decades of prayer elsewhere.'},
{q:'True or false: "Follow up between Hajj and Umrah, for they remove poverty and sins…"',tf:1,a:0,e:'True — "…as the bellows removes the dross of iron, gold and silver." (Tirmidhi 810)'},
{q:'Pilgrims are described by the Prophet ﷺ as…',o:['The soldiers of Allah','The delegation (guests) of Allah','The neighbours of the Kaaba','The people of the cloak'],a:1,e:'"If they call upon Him, He answers; if they seek His forgiveness, He forgives." (Ibn Majah 2892)'},
{q:'True or false: the Prophet ﷺ called Hajj and Umrah the jihad of the elderly, the young, the weak and women.',tf:1,a:0,e:'True — "The jihad of the elderly, the young, the weak and women is Hajj and Umrah" (Nasai 2626); and to Aishah (RA): "jihad in which there is no fighting" (Ibn Majah 2901).'},
{q:'Completing tawaf while keeping count of it is likened to…',o:['Fasting a month','Freeing a slave','A year of charity','Building a mosque'],a:1,e:'Tirmidhi 959 — and with every step a sin is erased and a good deed recorded.'},
{q:'"Zamzam water is…"',o:['Only for the sick','For whatever it is drunk for','Only for pilgrims','For wudu only'],a:1,e:'Ibn Majah 3062 — drink it with a specific dua: knowledge, cure, forgiveness, whatever you need.'},
{q:'True or false: the Prophet ﷺ called Makkah the most beloved of Allah’s land to Allah.',tf:1,a:0,e:'True — "Had I not been driven out of you, I would never have left." (Tirmidhi 3925)'},
{q:'True or false: because the Haram multiplies reward, wrongdoing there is also graver.',tf:1,a:0,e:'True — Allah warns against "deviation to wrongdoing" in the Haram (Quran 22:25). Guard your tongue and gaze doubly.'}
]},
{icon:'🕌',name:'Level 6 · Madinah — City of the Prophet ﷺ',desc:'Virtues & etiquette of the visit',study:{sub:'learn',id:'madCard'},qs:[
{q:'One prayer in Masjid an-Nabawi is better than…',o:['100 elsewhere','1,000 elsewhere (except al-Masjid al-Haram)','100,000 elsewhere','70 elsewhere'],a:1,e:'Bukhari 1190 — a thousand-fold, exceeded only by Masjid al-Haram.'},
{q:'The Rawdah is described by the Prophet ﷺ as…',o:['The best of gardens','A garden from the gardens of Paradise','His private courtyard','The first masjid'],a:1,e:'"Between my house and my minbar is a garden from the gardens of Paradise." (Bukhari 1195)'},
{q:'Visiting the Rawdah requires…',o:['Nothing — walk in anytime','A paid ticket','A free timed permit via the Nusuk app','A tour guide'],a:2,e:'Book the free permit on Nusuk as soon as your dates are confirmed — slots run out.'},
{q:'Praying 2 rakahs in Masjid Quba (with wudu from home) equals…',o:['A Hajj','An Umrah','40 years of prayer','Nothing specific'],a:1,e:'Ibn Majah 1412 — and the Prophet ﷺ visited Quba every Saturday.'},
{q:'True or false: Madinah is a sacred sanctuary (haram) just as Makkah is.',tf:1,a:0,e:'True — the Prophet ﷺ declared Madinah sacred between its two lava plains (Muslim 1374).'},
{q:'True or false: the Dajjal and the plague can enter Madinah.',tf:1,a:1,e:'False — "There are angels at the entrances of Madinah: neither plague nor the Dajjal can enter it." (Bukhari 1880)'},
{q:'Masjid al-Qiblatayn is famous because…',o:['It has two minarets','The qibla changed there mid-prayer','It is the oldest mosque','The Prophet ﷺ was born there'],a:1,e:'The congregation turned from Jerusalem to the Kaaba in a single prayer (Quran 2:144).'},
{q:'The Prophet ﷺ said about Uhud…',o:['"It is a cursed mountain"','"It is a mountain that loves us and we love it"','"Never climb it"','"It guards the city"'],a:1,e:'Bukhari 4083 — at its foot rest Hamza (RA) and the seventy martyrs of Uhud.'},
{q:'Who rests beside the Prophet ﷺ in his chamber?',o:['Hamza & Abbas','Abu Bakr & Umar','Uthman & Ali','His wives'],a:1,e:'His two closest companions and successors — greet all three with a calm salam.'},
{q:'True or false: visiting Madinah is a required rite of Umrah.',tf:1,a:1,e:'False — beloved and highly virtuous (one of the three mosques worth travelling to — Bukhari 1189), but not part of the Umrah rites, and it needs no ihram.'},
{q:'"Whoever eats seven ___ dates in the morning will not be harmed that day by poison or magic."',o:['Sukkari','Ajwa','Medjool','Barhi'],a:1,e:'Ajwa dates of Madinah (Bukhari 5779) — the perfect gift to bring home.'},
{q:'True or false: the Prophet ﷺ will intercede for the one who dies in Madinah.',tf:1,a:0,e:'True — "Whoever is able to die in Madinah, let him die there, for I will intercede for him." (Tirmidhi 3917)'}
]},
{icon:'⚖️',name:'Level 7 · Fiqh essentials — Q&A',desc:'Rulings, nuances & common doubts',study:{sub:'learn',id:'qaCard'},qs:[
{q:'Can you perform Umrah on behalf of a deceased parent?',o:['Never','Yes — after having performed your own Umrah first','Only during Hajj season','Only for mothers'],a:1,e:'Badal is established: "Labbayk on behalf of Shubrumah…" — the Prophet ﷺ said to perform your own first, then his (Abu Dawud 1811).'},
{q:'True or false: you may perform a second Umrah in the same trip by taking ihram from Tan’eem.',tf:1,a:0,e:'True — the Prophet ﷺ sent Aishah (RA) with her brother to Tan’eem for exactly this (Bukhari 1784).'},
{q:'How many Umrahs did the Prophet ﷺ perform?',o:['One','Two','Four','Seven'],a:2,e:'Four: Hudaybiyyah, al-Qada, al-Ji’ranah, and the one with his Hajj (Bukhari 1778).'},
{q:'Your wudu breaks in round 5 of tawaf. What happens?',o:['The whole Umrah is invalid','Renew wudu and continue — completed rounds are not lost','You must restart from round 1 tomorrow','Nothing — wudu is optional'],a:1,e:'Renew your wudu and return; resume the interrupted round (or repeat it to be safe). No panic, nothing is ruined.'},
{q:'True or false: you may pause tawaf or sa’i to rest, drink Zamzam, or join the obligatory prayer, then continue.',tf:1,a:0,e:'True — continue from where you left off. "Allah intends for you ease" (Quran 2:185).'},
{q:'A woman’s period begins after ihram. She…',o:['Cannot do Umrah at all','Continues everything except tawaf (and the sa’i after it) until pure','Does tawaf anyway','Must leave Makkah immediately'],a:1,e:'Ihram, talbiyah, dhikr and dua all continue; only the tawaf (and its sa’i) wait for purity (Bukhari 305).'},
{q:'True or false: skipping raml or idtiba’ invalidates the tawaf.',tf:1,a:1,e:'False — both are sunnah for men in the arrival tawaf only; leaving them affects nothing.'},
{q:'Tawaf in a wheelchair or on the upper floors is…',o:['Invalid','Valid only for the elderly','Fully valid','Half reward'],a:2,e:'Fully valid — the Prophet ﷺ himself performed tawaf mounted (Bukhari 1607).'},
{q:'True or false: speaking during tawaf breaks it, exactly like speaking in salah.',tf:1,a:1,e:'False — "Tawaf is like salah, except that Allah permitted speech in it; so speak only good." (Tirmidhi 960)'},
{q:'True or false: a man’s ihram garments must be brand new and pure white.',tf:1,a:1,e:'False — clean and unstitched is the requirement; white is recommended, new is not. Spares and washing are fine.'}
]}];

var DUAS=[
{t:'The Talbiyah',ar:'لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ، لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ، إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ، لَا شَرِيكَ لَكَ',tl:'Labbayk Allahumma labbayk, labbayka la sharika laka labbayk, innal-hamda wan-ni’mata laka wal-mulk, la sharika lak',tr:'Here I am O Allah, here I am. You have no partner, here I am. All praise, favour and sovereignty are Yours. You have no partner.',s:'Bukhari 1549'},
{t:'Entering the mosque',ar:'اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ',tl:'Allahumma-ftah li abwaba rahmatik',tr:'O Allah, open for me the gates of Your mercy.',s:'Muslim 713'},
{t:'Leaving the mosque',ar:'اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ',tl:'Allahumma inni as’aluka min fadlik',tr:'O Allah, I ask You of Your bounty.',s:'Muslim 713'},
{t:'Between the Yamani corner & Black Stone',ar:'رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ',tl:'Rabbana atina fid-dunya hasanah wa fil-akhirati hasanah wa qina ’adhaban-nar',tr:'Our Lord, give us good in this world and good in the Hereafter, and protect us from the punishment of the Fire.',s:'Quran 2:201 · Abu Dawud 1892'},
{t:'On Safa & Marwah',ar:'لَا إِلَٰهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ',tl:'La ilaha illallahu wahdahu la sharika lah, lahul-mulku wa lahul-hamdu wa huwa ’ala kulli shay’in qadir',tr:'None has the right to be worshipped but Allah alone, without partner. His is the dominion and the praise, and He is able to do all things. (Repeat 3× with your own duas between.)',s:'Muslim 1218'},
{t:'When drinking Zamzam',ar:'اللَّهُمَّ إِنِّي أَسْأَلُكَ عِلْمًا نَافِعًا وَرِزْقًا وَاسِعًا وَشِفَاءً مِنْ كُلِّ دَاءٍ',tl:'Allahumma inni as’aluka ’ilman nafi’an wa rizqan wasi’an wa shifa’an min kulli da’',tr:'O Allah, I ask You for beneficial knowledge, abundant provision, and cure from every illness. (Reported from Ibn Abbas RA)',s:'"Zamzam is for whatever it is drunk for" — Ibn Majah 3062'},
{t:'The travel dua',ar:'سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَٰذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ وَإِنَّا إِلَىٰ رَبِّنَا لَمُنْقَلِبُونَ',tl:'Subhanalladhi sakhkhara lana hadha wa ma kunna lahu muqrinin, wa inna ila Rabbina lamunqalibun',tr:'Glory to Him who has subjected this to us, and we could never have it by our efforts. Surely to our Lord we are returning.',s:'Quran 43:13-14 · Muslim 1342'},
{t:'Salam upon the Prophet ﷺ (in Madinah)',ar:'السَّلَامُ عَلَيْكَ يَا رَسُولَ اللَّهِ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ',tl:'As-salamu ’alayka ya Rasulallah wa rahmatullahi wa barakatuh',tr:'Peace be upon you, O Messenger of Allah, and the mercy of Allah and His blessings. (Then salam upon Abu Bakr and ’Umar.)',s:'Etiquette: calm voice, no crowding'}];

